func (c *Cluster) kindPath(ctx context.Context) (string, error) {
	conf, err := c.Config(ctx)
	if err != nil {
		return "", err
	}

	kindPath, err := exec.LookPath("kind")
	if err != nil {
		kindPath = c.GetBinPath("kind" + conf.BinSuffix)
		err = file.DownloadWithCache(ctx, conf.CacheDir, conf.KindBinary, kindPath, 0755, conf.QuietPull)
		if err != nil {
			return "", err
		}
	}
	return kindPath, nil
}
